45	    const props = {
46	      data: 'test string',
47	      headers: [{ name: 'Content-Type', value: 'text/plain', required: true }],
48	    }
49	    const { dataUrl } = processResponseBody(props)
50	    expect(dataUrl).toBe('mockedBlobURL')
