54	    const props = {
55	      data: { key: 'value' },
56	      headers: [{ name: 'Content-Type', value: 'application/json', required: true }],
57	    }
58	    const { dataUrl } = processResponseBody(props)
59	    expect(dataUrl).toBe('mockedBlobURL')
