 *
 * A handler declares the MIME types it can decode (with optional wildcard glob
 * patterns) and provides an optional decode function that turns the raw response
 * body into a string or Blob.
 */
export type ResponseBodyHandler = {
  /** The MIME types this handler handles. Supports wildcard glob patterns (e.g. 'application/vnd.*+json'). */
  mimeTypes: string[]
  /**
   * Decode the raw response body into a string or Blob.
   *
   * Receives the full content type string so handlers can inspect parameters
   * such as the charset when decoding.
   */
  decode?: (buf: ArrayBuffer, contentType?: string) => string | Blob | Promise<string | Blob>
  /** A language identifier used for syntax highlighting the decoded body. */
  language?: string
}

